requestPayload.requestBody:
$merge([
    {
        "first_name": inputData.candidate.firstName,
        "last_name": inputData.candidate.lastName,
        "email": inputData.candidate.email,
        "mapped_url_token": $exists(inputData.candidate.customFields.publisherMetaData.utmTags.value) ? inputData.candidate.customFields.publisherMetaData.utmTags.value : $exists(inputData.candidate.customFields.publisherMetaData.trackParams.source) ? inputData.candidate.customFields.publisherMetaData.trackParams.source : "Joveo",
        "phone": inputData.candidate.phoneNumbers[
            0
        ].phoneNumber
    }, $merge( $map( $eval(inputData.candidate.customFields.jobMetaData.additionalFields.questions), function($q) { $exists($lookup(inputData.candidate.customFields.questionAnswers, $q.label)) ? ( $q.inputType='SELECT' ? ( $q.isMultiValue = true ? { ($q.id): [$map( $lookup(inputData.candidate.customFields.questionAnswers, $q.label), function($ans) { $filter($q.inputOptionList, function($opt) { $opt.label = $ans
                    })[
                        0
                    ].value
                } )
            ]
        } : { ($q.id): $filter($q.inputOptionList, function($opt) { $opt.label = $lookup(inputData.candidate.customFields.questionAnswers, $q.label)
            })[
                0
            ].value
        } ) : { ($q.id): $lookup(inputData.candidate.customFields.questionAnswers, $q.label)
        } ) : {}
    } ) ) , $exists(inputData.application.attachment.attachmentContent) ? {
        "resume_content": inputData.application.attachment.attachmentContent
    } : {}, $exists(inputData.application.attachment.attachmentFileName) ? {
        "resume_content_filename": inputData.application.attachment.attachmentFileName
    } : {}, $exists(inputData.candidate.customFields.questionAnswers.additionalFields)?inputData.candidate.customFields.questionAnswers.additionalFields: {}
])

