    $inputType := function($input) { $input = "input_text" ? "TEXT" :$input = "textarea" ? "TEXT_AREA" : $input = "multi_value_single_select" ? "SELECT" : $input = "multi_value_multi_select" ? "SELECT" : $input = "input_file" ? "RESUME" : "UNKNOWN" };
     $additionalField := function($input) { $substring($input, 0, 8) = "question" }; 
     $multiValueMultiSelectFieldName := function($input) { $input.type = "multi_value_multi_select" ? $replace($input.name, "[]", ""):$input.name};
     $questionObj := function($srQuestion, $srQuestionField) 
     { 
         { 
            "type": "QUESTION", 
            "id": $multiValueMultiSelectFieldName($srQuestionField) , 
            "label": $srQuestion.label, 
