            "properties": { 
                "isMandatory": $srQuestion.required 
            }, 
            "inputOptionList": $srQuestionField.values 
        } 
    }; 


        $map($filter(questions, function($question) {$additionalField($question.fields[0].name)}),function($question) { 
              $questionObj($question, $question.fields[0])}) ), 
